// Small numeric and random helpers shared by every layer. No DOM, no state.

export const rand = (a, b) => a + Math.random() * (b - a);
export const pick = a => a[Math.floor(Math.random() * a.length)];
export const clamp = (x, a, b) => Math.min(b, Math.max(a, x));
export const mod12 = x => ((x % 12) + 12) % 12;
export const near = (a, b) => Math.abs(a - b) < 1e-6;

// weighted pick; falls back to a uniform pick when no weight is positive
export function wpick(items, weights) {
  let sum = 0;
  for (const w of weights) sum += w;
  if (!(sum > 0)) return pick(items);
  let r = Math.random() * sum;
  for (let i = 0; i < items.length; i++) { r -= weights[i]; if (r <= 0) return items[i]; }
  return items[items.length - 1];
}

// Observer: a minimal event emitter. Services (Transport, MidiOutput) extend it so views can
// follow them without the services knowing anything about the DOM.
export class Emitter {
  #handlers = new Map();

  on(type, fn) {
    if (!this.#handlers.has(type)) this.#handlers.set(type, new Set());
    this.#handlers.get(type).add(fn);
    return () => this.off(type, fn);
  }

  off(type, fn) {
    this.#handlers.get(type)?.delete(fn);
  }

  emit(type, payload) {
    for (const fn of [...(this.#handlers.get(type) ?? [])]) fn(payload);
  }
}

// localStorage that never throws (private mode, blocked storage).
export const loadPref = key => { try { return localStorage.getItem(key); } catch (e) { return null; } };
export const savePref = (key, v) => { try { localStorage.setItem(key, v); } catch (e) { /* storage blocked */ } };

import { mod12 } from "../core/util.js";

// Consonance of an interval (semitones, any tuning): peaks at just ratios and
// their 12/24-TET neighbours, Gaussian falloff (sigma 0.15 semitone).
const ANCHORS = [
  [0, 1], [7.02, .92], [7, .92], [3.86, .8], [4, .8], [3.16, .78], [3, .78],
  [8.84, .66], [9, .66], [4.98, .62], [5, .62], [3.47, .6], [3.5, .6], [8.14, .58], [8, .58],
  [9.69, .5], [8.53, .45], [8.5, .45], [10, .45], [2.67, .42], [10.18, .42], [9.96, .42],
  [2.04, .4], [2, .4], [4.35, .4], [1.82, .36], [9.5, .34], [10.49, .32], [10.5, .32],
  [5.51, .3], [2.5, .3], [4.5, .28], [10.88, .28], [11, .28], [7.5, .26], [1.51, .25], [1.5, .25],
  [5.83, .25], [5.5, .24], [6.17, .22], [6.49, .2], [6.5, .2], [6, .18], [11.5, .16],
  [1.12, .12], [1, .12], [.5, .1],
];
const consMemo = new Map();   // polymetric lanes ask for the same intervals many times

export function cons(iv) {
  const x = mod12(iv), key = Math.round(x * 1e4);
  const hit = consMemo.get(key);
  if (hit !== undefined) return hit;
  let best = .05;
  for (const [a, w] of ANCHORS) {
    let d = Math.abs(x - a);
    if (d > 6) d = 12 - d;
    if (d > .5) continue;
    const v = w * Math.exp(-d * d * 44.4);
    if (v > best) best = v;
  }
  consMemo.set(key, best);
  return best;
}

import { mod12 } from "../core/util.js";

// Note spelling: letter + accidental (quarter tones included) and cents for JI.
export const LET = ["C", "D", "E", "F", "G", "A", "B"];
export const NAT = [0, 2, 4, 5, 7, 9, 11];
const ACC = { "-2": "𝄫", "-1.5": "♭↓", "-1": "♭", "-0.5": "↓", "0": "", "0.5": "↑", "1": "♯", "1.5": "♯↑", "2": "𝄪" };
export const accStr = a => ACC[String(Math.round(a * 2) / 2 || 0)] ?? "";
const normAcc = a => ((a % 12) + 18) % 12 - 6;
const wrap7 = L => ((L % 7) + 7) % 7;

// Letter offset for an interval in a non-heptatonic scale (S = set of semitone classes).
function letterOffset(iv, S) {
  switch (iv) {
    case 0: return 0;
    case 1: case 2: return 1;
    case 3: return S.has(4) && !S.has(2) ? 1 : 2;
    case 4: return 2;
    case 5: return 3;
    case 6: return S.has(5) ? 4 : 3;
    case 7: return 4;
    case 8: return S.has(7) || S.has(9) ? 5 : 4;
    case 9: return 5;
    default: return 6;
  }
}
function spellAt(target, Lp, strict) {
  let L = wrap7(Lp), acc = normAcc(target - NAT[L]);
  if (!strict && Math.abs(acc) > 1) {
    for (const d of [-1, 1]) {
      const L2 = wrap7(Lp + d), a2 = normAcc(target - NAT[L2]);
      if (Math.abs(a2) < Math.abs(acc)) { L = L2; acc = a2; }
    }
  }
  return { L, acc };
}
// strict: one letter per degree (7-note scales). JI notes are spelled by the nearest
// 12-TET pitch and keep their deviation in cents.
export function spellList(semis, rootPc, root, ppo, strict) {
  const ji = ppo === 43;
  const vals = semis.map(s => (ji ? Math.round(s) : s));
  const S = new Set(vals.map(v => mod12(Math.floor(v + 1e-9))));
  return semis.map((s, i) => {
    const v = vals[i];
    const Lp = root.L + (strict ? i : letterOffset(mod12(Math.floor(v + 1e-9)), S));
    const sp = spellAt(rootPc + v, Lp, strict);
    sp.cents = ji ? Math.round((s - v) * 100) : 0;
    return sp;
  });
}
// candidate spellings [letter, accidental] for each pitch class of the root
export const ROOTS = { 0: [[0, 0]], 1: [[0, 1], [1, -1]], 2: [[1, 0]], 3: [[2, -1], [1, 1]], 4: [[2, 0]], 5: [[3, 0]], 6: [[3, 1], [4, -1]], 7: [[4, 0]], 8: [[4, 1], [5, -1]], 9: [[5, 0]], 10: [[6, -1], [5, 1]], 11: [[6, 0]] };
export const pcName = sp => LET[sp.L] + accStr(sp.acc);
export function noteName(m, sp) {
  const oct = Math.round((m - sp.cents / 100 - sp.acc - NAT[sp.L]) / 12) - 1;
  return LET[sp.L] + accStr(sp.acc) + oct;
}
// ASCII form for Coypu comments
export const asciiName = s => s.replace(/♯/g, "#").replace(/♭/g, "b").replace(/↑/g, "+").replace(/↓/g, "-");

import { mod12, near } from "../core/util.js";
import { TUNING } from "../data/tunings.js";
import { cons } from "./consonance.js";
import { ROOTS, spellList } from "./spelling.js";

// The scale context: a scale on a root, with its degrees in semitones, their spelling and the tonic.
// { scale, rootPc, root: {L, acc}, asc: number[], degs: [{s, sp, asc, desc, ai, step}], tonic }
export function buildCtx(scale, rootPc) {
  const T = TUNING[scale.ppo].semis;
  const asc = scale.deg.map(d => T[d]);
  const desc = scale.desc ? scale.desc.map(d => T[d]) : null;
  const major = asc.some(s => Math.abs(s - 4) < .05);
  const cands = ROOTS[rootPc].slice();
  if ((rootPc === 1 || rootPc === 8) && major) cands.reverse();
  const tryMode = strict => {
    let best = null;
    for (const [L, acc] of cands) {
      const root = { L, acc };
      const a = spellList(asc, rootPc, root, scale.ppo, strict);
      const d = desc ? spellList(desc, rootPc, root, scale.ppo, strict) : null;
      let cost = 0;
      for (const sp of d ? a.concat(d) : a) cost += Math.abs(sp.acc) + (Math.abs(sp.acc) > 1.5 ? 100 : 0);
      if (!best || cost < best.cost - 1e-9) best = { root, a, d, cost };
    }
    return best;
  };
  let sp = asc.length === 7 ? tryMode(true) : null;
  if (!sp || sp.cost >= 100) sp = tryMode(false);
  const degs = asc.map((s, i) => ({ s, sp: sp.a[i], asc: true, desc: !desc || desc.some(x => near(x, s)), ai: i, step: scale.deg[i] }));
  if (desc) desc.forEach((s, i) => {
    if (!asc.some(x => near(x, s))) degs.push({ s, sp: sp.d[i], asc: false, desc: true, ai: -1, step: scale.desc[i] });
  });
  // Partch otonalities: degree 0 can be a high harmonic, so centre on the degree most
  // consonant with the others (the fundamental of the series).
  let tonic = 0;
  if (scale.ppo === 43) {
    let best = -1;
    asc.forEach((s, j) => {
      let sum = 0, b3 = 0, b5 = 0;
      asc.forEach((x, k) => {
        if (k === j) return;
        const iv = mod12(x - s), c = cons(iv);
        sum += c;
        if (iv > 2.6 && iv < 4.6) b3 = Math.max(b3, c);
        if (iv > 5.9 && iv < 8.1) b5 = Math.max(b5, c);
      });
      if (sum + b3 + b5 > best + 1e-9) { best = sum + b3 + b5; tonic = j; }
    });
  }
  return { scale, rootPc, root: sp.root, asc, degs, tonic };
}

import { mod12, wpick } from "../core/util.js";
import { cons } from "./consonance.js";
import { pcName } from "./spelling.js";

// The chord on degree j of the scale: root, third and fifth (the most consonant ones in
// non-heptatonic scales), and the set of degrees that count as chord tones.
export function chordOn(ctx, j) {
  const P = ctx.asc, n = P.length, r = P[j];
  let t = null, f = null;
  if (n === 7) { t = (j + 2) % 7; f = (j + 4) % 7; }
  else {
    let wt = 0, wf = 0;
    for (let k = 0; k < n; k++) {
      if (k === j) continue;
      const iv = mod12(P[k] - r), c = cons(iv);
      if (iv > 2.6 && iv < 4.6 && c > wt) { wt = c; t = k; }
      if (iv > 5.9 && iv < 8.1 && c > wf) { wf = c; f = k; }
    }
  }
  const ivOf = k => (k == null ? null : mod12(P[k] - r));
  const tones = new Set([j, ...[t, f].filter(k => k != null && cons(ivOf(k)) >= .3)]);
  return { j, r, iv3: ivOf(t), iv5: ivOf(f), tones };
}

export function chordLabel(ctx, ch) {
  const sp = ctx.degs[ch.j].sp, name = pcName(sp);
  if (ctx.scale.ppo === 43) return name + (sp.cents ? `${sp.cents > 0 ? "+" : "−"}${Math.abs(sp.cents)}¢` : "");
  if (ctx.scale.ppo !== 12) return name;
  const a = ch.iv3, b = ch.iv5;
  if (a === 3) return name + (b === 6 ? "°" : "m");
  if (a === 4) return name + (b === 8 ? "+" : "");
  if (a === 2) return name + "sus2";
  if (a === 5) return name + "sus4";
  return name + (b === 7 ? "5" : "");
}

// A progression as text: repeats are folded ("Am ▸ F ×2").
export function harmonyText(ctx, h) {
  const labels = h.map(c => chordLabel(ctx, c)), n = labels.length;
  if (n === 1) return labels[0];
  if (h.every(c => c.j === h[0].j)) return `${labels[0]} ${n === 2 ? "both bars" : "all bars"}`;
  for (const P of [2, 4]) {
    if (P < n && n % P === 0 && h.every((c, b) => c.j === h[b % P].j)) return `${labels.slice(0, P).join(" ▸ ")} ×${n / P}`;
  }
  return labels.join(" ▸ ");
}

// Root motion preference from the tonic: IV, V, bVII, bVI, vi, bIII...
const MOTION = [[5, 1], [7, .9], [10, .8], [8, .75], [9, .6], [3, .6], [2, .45], [1, .4], [4, .35], [11, .15], [6, .08]];
function motionW(iv) {
  let b = .05;
  for (const [a, w] of MOTION) { let d = Math.abs(iv - a); d = Math.min(d, 12 - d); b = Math.max(b, w * Math.exp(-d * d * 4)); }
  return b;
}
function pickChordDegree(ctx) {
  const idx = ctx.asc.map((_, j) => j);
  const t0 = ctx.asc[ctx.tonic];
  const ws = ctx.asc.map((s, j) => {
    if (j === ctx.tonic) return 0;
    const ch = chordOn(ctx, j);
    const q5 = ch.iv5 == null ? .15 : cons(ch.iv5);
    const q3 = ch.iv3 == null ? .5 : .55 + .45 * cons(ch.iv3);
    return motionW(mod12(s - t0)) * q5 * q3;
  });
  return wpick(idx, ws);
}
// One chord per bar. Up to 4 bars the progression is new; 8 bars repeat it, sometimes with a
// different last bar as a turnaround.
export function makeHarmony(ctx, bars) {
  const T = chordOn(ctx, ctx.tonic);
  if (bars <= 1) return [T];
  const P = Math.min(bars, 4), phrase = [T];
  while (phrase.length < P) phrase.push(Math.random() < (P === 2 ? .3 : .15) ? T : chordOn(ctx, pickChordDegree(ctx)));
  const h = Array.from({ length: bars }, (_, b) => phrase[b % P]);
  if (bars > P && Math.random() < .5) h[bars - 1] = chordOn(ctx, pickChordDegree(ctx));
  return h;
}

// Pattern and lane lengths, and the pure track queries built on them.
//
// The pattern (MASTERS) sets the chord bars and restarts every lane when it ends. Each lane loops
// on its own length (MINL..MAXL) inside it. Lanes store MAXL steps, so shortening a lane and
// lengthening it again brings the same steps back.
//
// A track: { len, gates[], notes[], vel[], dur[], src, edited, muted, gate, gateSet }

export const MASTERS = [16, 32, 64, 128], MINL = 3, MAXL = 64;
export const barsOf = M => Math.ceil(M / 16);
export const chordAt = (harmony, g) => harmony[Math.floor(g / 16) % harmony.length];

// pattern positions where lane step i is heard (a step past the pattern end is judged where it sits)
export function occ(i, L, M) {
  const out = [];
  for (let g = i; g < M; g += L) out.push(g);
  return out.length ? out : [i];
}
export const isNote = (tr, i) => !!(tr.gates[i] && tr.notes[i]);
// steps from note i to the next note in the lane's own loop
export function gapIn(tr, i) {
  const L = tr.len;
  for (let d = 1; d < L; d++) if (isNote(tr, (i + d) % L)) return d;
  return L;
}
// steps from pattern step g to this lane's next note while playing (the lane restarts at the pattern end)
export function gapAhead(tr, g, M) {
  for (let d = 1; d <= M; d++) { const g2 = (g + d) % M; if (isNote(tr, g2 % tr.len)) return d; }
  return M;
}
// a note never outlasts the gap to the next one, so lanes stay monophonic (as Coypu's asSeq does)
export const effDur = (tr, i) => Math.max(1, Math.min(tr.dur[i] || 1, gapIn(tr, i)));
// for each step: the note holding it (-1 if none), and whether it is the note's last step
export function coverage(tr) {
  const L = tr.len, owner = Array(L).fill(-1), end = Array(L).fill(false);
  for (let i = 0; i < L; i++) {
    if (!isNote(tr, i)) continue;
    const d = effDur(tr, i);
    for (let s = 1; s < d; s++) { const j = (i + s) % L; owner[j] = i; end[j] = s === d - 1; }
  }
  return { owner, end };
}
// note under step i: itself, the note holding it, or -1
export function ownerOf(tr, i) { return isNote(tr, i) ? i : coverage(tr).owner[i]; }
// length of note `own` when dragged to step j: up to j going forward (across the loop end too),
// the most it can have when dragged past the next note, one step when dragged back before it
export function dragDur(tr, own, j) {
  const L = tr.len, gap = gapIn(tr, own), f = (j - own + L) % L;
  if (f < gap) return f + 1;
  return j > own ? gap : 1;
}

import { pick, rand } from "../core/util.js";
import { WORLD } from "../data/rhythms.js";
import { MAXL } from "./timeline.js";

const tile = (pat, N) => Array.from({ length: N }, (_, i) => pat[i % pat.length]);
const count = g => g.reduce((a, b) => a + b, 0);

// Gates are made for all MAXL steps; at least two hits must fall inside the lane length L.
// A world rhythm is tiled, so the first L steps are exactly Coypu's `L name`.
// pRandom: chance of a random rhythm; used: world rhythm names other lanes already have.
export function makeRhythm(L, pRandom, used) {
  if (Math.random() >= pRandom) {
    const fits = w => count(tile(w.pat, L)) >= 2;
    const fresh = WORLD.filter(w => !used.has(w.name) && fits(w));
    const w = pick(fresh.length ? fresh : WORLD.filter(fits));
    if (w) {
      used.add(w.name);
      return { gates: tile(w.pat, MAXL), src: { kind: "world", name: w.name, origin: w.origin } };
    }
  }
  const prob = Math.round(rand(15, 70));
  let g, tries = 0;
  do { g = Array.from({ length: MAXL }, () => (Math.random() < prob / 100 ? 1 : 0)); } while (count(g.slice(0, L)) < 2 && ++tries < 40);
  if (count(g.slice(0, L)) < 2) { g[0] = 1; g[Math.floor(L / 2)] = 1; }
  return { gates: g, src: { kind: "random", prob } };
}

import { clamp, rand } from "../core/util.js";

// The three synth lanes. Index k is used everywhere: track k, voice k, MIDI channel k + 1.
// hold: notes usually last until the next one, up to this many steps; maxDur, longP: occasional
// long notes, likelier on strong beats; shortP: chance of a single step; gf: gate range (gateTimes)
export const ROLE = [
  { key: "saw", name: "Saw", role: "bass", lo: 24, hi: 48, spread: 10, tau: 1.45, hold: 2, maxDur: 4, longP: .15, shortP: .35, gf: [.55, .9] },
  { key: "square", name: "Square", role: "mid", lo: 48, hi: 70, center: 59, spread: 7, tau: 1.2, hold: 2, maxDur: 4, longP: .2, shortP: .3, gf: [.45, .85] },
  { key: "tri", name: "Tri", role: "lead", lo: 62, hi: 86, center: 73, spread: 8, tau: 1.15, hold: 3, maxDur: 8, longP: .35, shortP: .15, gf: [.6, .95] },
];
// Metric weight of each 16th in a bar
export const BEAT = [1, .2, .45, .25, .75, .2, .45, .25, .9, .2, .45, .25, .75, .2, .45, .25];
export const roundGate = x => clamp(Math.round(x * 20) / 20, .25, 1);
export const randGate = R => roundGate(rand(R.gf[0], R.gf[1]));
export function genDur(R, step, gap) {
  const cap = Math.min(gap, R.maxDur);
  let d = Math.min(gap, R.hold);
  if (cap > d && Math.random() < R.longP * (.4 + BEAT[step % 16])) d += 1 + Math.floor(Math.random() * (cap - d));
  else if (d > 1 && Math.random() < R.shortP) d = 1;
  return d;
}

import { clamp, near, rand, wpick } from "../core/util.js";
import { cons } from "../theory/consonance.js";
import { BEAT, ROLE, genDur } from "./roles.js";
import { MAXL, chordAt, gapIn, isNote, occ } from "./timeline.js";

// The pitches of the scale context inside [lo, hi], sorted: [{m, d}] with d the scale degree
export function poolFor(ctx, lo, hi) {
  const out = [];
  for (let o = 0; o <= 10; o++) for (const d of ctx.degs) {
    const m = 12 * o + ctx.rootPc + d.s;
    if (m >= lo - 1e-6 && m <= hi + 1e-6) out.push({ m, d });
  }
  return out.sort((a, b) => a.m - b.m);
}
// Scale steps between two pitches, honouring ascending/descending forms
function stepsBetween(pool, a, b) {
  if (near(a, b)) return 0;
  const lo = Math.min(a, b), hi = Math.max(a, b), up = b > a;
  let n = 1;
  for (const q of pool) if (q.m > lo + 1e-6 && q.m < hi - 1e-6 && (up ? q.d.asc : q.d.desc)) n++;
  return n;
}
function melodic(p, prev, role, lastLeap, pool) {
  const L = p.m - prev.m, A = Math.abs(L), n = stepsBetween(pool, prev.m, p.m);
  if (role === "bass") {
    if (n === 0) return 1;
    if (Math.abs(A - 12) < .3) return .9;
    if (Math.abs(A - 7) < .3 || Math.abs(A - 5) < .3) return .75;
    if (n === 1) return .6;
    return .5 * Math.exp(-A / 7);
  }
  let w = n === 0 ? (role === "mid" ? .6 : .42) : n === 1 ? 1 : n === 2 ? .75 : n === 3 ? .5 : .36 * Math.exp(-(n - 4) / 2.2);
  if (Math.abs(A - 12) < .3) w = Math.max(w, .3);
  if (Math.abs(lastLeap) > 4.5 && n > 0) {          // leap recovery
    if (Math.sign(L) === -Math.sign(lastLeap)) { if (n <= 2) w *= 1.6; }
    else w *= .55;
  }
  return w;
}
// o.occ: the pattern positions where this step is heard. With lanes shorter than the pattern a
// step comes back over several chords, so the vertical fit (chord, metric strength, bass, mid)
// is a geometric mean over all of them: one bad clash pulls a note down.
export function noteWeights(k, pool, o, harmony, ctx) {
  const R = ROLE[k];
  const per = o.occ.map(g => {
    const chord = chordAt(harmony, g), s = BEAT[g % 16];
    let e = R.role === "bass" ? .8 + 2.4 * s : .5 + 1.8 * s;
    if (o.isFirst) e = Math.max(e, R.role === "bass" ? 2.6 : 1.6);
    return { root: ctx.rootPc + chord.r, tones: chord.tones, e, bass: o.refs.bassAt[g] ?? null, mid: o.refs.midAt[g] ?? null };
  });
  const chord0 = chordAt(harmony, o.occ[0]);
  let center = R.center;
  if (R.role === "bass") { const low = pool.find(p => p.d.ai === chord0.j); center = (low ? low.m : R.lo + 5) + 5; }
  return pool.map(p => {
    if (o.prev) {
      const L = p.m - o.prev.m;
      if ((L > 1e-6 && !p.d.asc) || (L < -1e-6 && !p.d.desc)) return 0;
    } else if (!p.d.asc) return 0;
    let lw = 0;
    for (const q of per) {
      let h = cons(p.m - q.root);
      if (q.tones.has(p.d.ai)) h += (1 - h) * .45;
      let v = Math.pow(h, q.e);
      if (R.role !== "bass" && q.bass != null) v *= Math.pow(cons(p.m - q.bass), 1.3);
      if (R.role === "lead" && q.mid != null) {
        v *= Math.pow(cons(p.m - q.mid), 1.1);
        if (near(p.m, q.mid)) v *= .25;
      }
      lw += Math.log(v + 1e-12);
    }
    let w = Math.exp(lw / per.length);
    if (o.prev) {
      w *= melodic(p, o.prev, R.role, o.lastLeap, pool);
      if (near(p.m, o.prev.m)) w *= R.role === "bass" ? Math.pow(.8, Math.max(0, (o.run || 1) - 1)) : Math.pow(.5, o.run || 1);
    }
    if (o.next) w *= .45 + .55 * melodic(o.next, p, R.role, 0, pool);   // lead back into the loop
    const z = (p.m - center) / R.spread;
    return w * Math.exp(-z * z);
  });
}
// What the bass and mid play at each pattern position, following each lane's own loop.
// Positions past the pattern end are filled too, for lane steps the pattern never reaches.
export function voiceRefs(tracks, steps) {
  const G = Math.max(steps, MAXL), T = tracks;
  const bassAt = Array(G).fill(null), midAt = Array(G).fill(null);
  const b = T[0];
  if (b && b.notes) {
    const L = b.len, held = Array(L).fill(null);
    let last = null;
    for (let i = 0; i < L; i++) if (isNote(b, i)) last = b.notes[i].m;   // the loop's last note carries into its start
    for (let i = 0; i < L; i++) { if (isNote(b, i)) last = b.notes[i].m; held[i] = last; }
    for (let g = 0; g < G; g++) bassAt[g] = held[g % L];
  }
  const md = T[1];
  if (md && md.notes) for (let g = 0; g < G; g++) { const i = g % md.len; if (isNote(md, i)) midAt[g] = md.notes[i].m; }
  return { bassAt, midAt };
}
// Notes, velocities and durations for steps 0..len-1 of lane k in an M-step pattern; steps past
// its length are cleared and get notes when the lane grows over them.
export function genNotes(k, tr, ctx, harmony, rf, M) {
  const R = ROLE[k], L = tr.len, pool = poolFor(ctx, R.lo, R.hi);
  tr.notes.fill(null);
  const hits = [];
  for (let i = 0; i < L; i++) if (tr.gates[i]) hits.push(i);
  let prev = null, lastLeap = 0, first = null, run = 0;
  hits.forEach((step, h) => {
    const oc = occ(step, L, M);
    const newBar = h === 0 || Math.floor(hits[h - 1] / 16) !== Math.floor(step / 16);
    let c = null;
    if (R.role === "bass" && newBar && Math.random() < .85) {          // anchor each bar on the chord root...
      const js = new Set(oc.map(g => chordAt(harmony, g).j));
      if (js.size === 1) {                                              // ...when it meets the same chord every time
        const j = oc.length ? chordAt(harmony, oc[0]).j : 0;
        const roots = pool.filter(p => p.d.ai === j);
        if (roots.length) c = roots.length > 1 && Math.random() < .2 ? roots[1] : roots[0];
      }
    }
    if (!c) {
      const isLast = h === hits.length - 1 && hits.length > 2;
      const ws = noteWeights(k, pool, { occ: oc, prev, lastLeap, run, next: isLast ? first : null, isFirst: h === 0, refs: rf }, harmony, ctx);
      c = wpick(pool, ws.map(w => Math.pow(w, R.tau)));
    }
    if (prev) lastLeap = c.m - prev.m;
    run = prev && near(c.m, prev.m) ? run + 1 : 1;
    prev = c;
    if (!first) first = c;
    tr.notes[step] = c;
    tr.vel[step] = clamp(.7 + .3 * BEAT[step % 16] + rand(-.06, .06), .45, 1);
  });
  hits.forEach(step => { tr.dur[step] = genDur(R, step, gapIn(tr, step)); });
}

import { clamp, pick } from "../core/util.js";
import { SCALES } from "../data/scales.js";
import { buildCtx } from "../theory/scale-context.js";
import { makeHarmony } from "../theory/chords.js";
import { genNotes, noteWeights, poolFor, voiceRefs } from "./melody.js";
import { makeRhythm } from "./rhythm.js";
import { BEAT, ROLE, genDur, randGate, roundGate } from "./roles.js";
import { MASTERS, MAXL, MINL, barsOf, effDur, gapIn, isNote, occ } from "./timeline.js";
import { wpick } from "../core/util.js";

// The model: everything the dice decided and everything the user edited. No DOM, no audio.
// Methods that change the pattern return false when nothing changed, so the caller can skip a redraw.
export class Session {
  ctx = null;          // scale context, see buildCtx
  steps = 16;          // pattern length, one of MASTERS
  bpm = 136;
  rnd = 60;            // % of lanes that get a random rhythm instead of a world rhythm
  micro = true;        // microtonal scales allowed
  kickOn = true;
  harmony = [];        // one chord per bar
  tracks = [];         // one per ROLE

  get stepDuration() { return 60 / this.bpm / 4; }

  availableScales() { return SCALES.filter(s => this.micro || s.ppo === 12); }

  refs() { return voiceRefs(this.tracks, this.steps); }

  /* ------------------------------ dice ------------------------------ */
  roll() {
    this.ctx = buildCtx(this.#pickScale(), Math.floor(Math.random() * 12));
    this.regenerate();
  }
  regenerate() {
    this.harmony = makeHarmony(this.ctx, barsOf(this.steps));
    const used = new Set();
    for (let k = 0; k < ROLE.length; k++) this.#genTrack(k, used);
  }
  rerollTrack(k) {
    const used = new Set(this.tracks.filter((t, i) => i !== k && t.src.kind === "world").map(t => t.src.name));
    this.#genTrack(k, used);
  }

  /* ----------------------------- lengths ---------------------------- */
  // New pattern length: new chords for the new number of bars, lanes that matched the old length
  // follow it, rhythms stay, notes and durations are picked again for the new chords.
  setMaster(M) {
    if (!MASTERS.includes(M) || M === this.steps) return false;
    const follow = Math.min(this.steps, MAXL);
    this.steps = M;
    this.tracks.forEach(tr => { if (tr.len === follow) tr.len = Math.min(M, MAXL); });
    this.harmony = makeHarmony(this.ctx, barsOf(M));
    for (let k = 0; k < ROLE.length; k++) genNotes(k, this.tracks[k], this.ctx, this.harmony, this.refs(), this.steps);
    return true;
  }
  // Lane length: shorter hides steps without deleting them; longer brings back the hidden steps,
  // or continues the rhythm with new notes where there were none.
  setTrackLen(k, n) {
    const tr = this.tracks[k], old = tr.len;
    n = clamp(Math.round(n) || old, MINL, MAXL);
    if (n === old) return false;
    tr.len = n;
    const fresh = [];
    for (let i = old; i < n; i++) if (tr.gates[i] && !tr.notes[i]) { this.#pickNoteAt(k, i); fresh.push(i); }
    fresh.forEach(i => { tr.dur[i] = genDur(ROLE[k], i, gapIn(tr, i)); });
    return true;
  }

  /* ------------------------------ edits ----------------------------- */
  // A tap on a note removes it; on an empty or held step it starts a one-step note there.
  toggleStep(k, i) {
    const tr = this.tracks[k];
    if (isNote(tr, i)) { tr.gates[i] = 0; tr.notes[i] = null; }
    else { tr.gates[i] = 1; this.#pickNoteAt(k, i); tr.dur[i] = 1; }
    tr.edited = true;
  }
  setDur(k, i, d) {
    const tr = this.tracks[k];
    if (!isNote(tr, i)) return false;
    const v = clamp(Math.round(d), 1, gapIn(tr, i));
    if (v === effDur(tr, i) && v === tr.dur[i]) return false;
    tr.dur[i] = v;
    return true;
  }
  setGate(k, v) {
    const tr = this.tracks[k];
    tr.gate = roundGate(v);
    tr.gateSet = true;
  }
  // k = -1 is the kick. Returns whether the lane is now muted.
  toggleMute(k) {
    if (k < 0) { this.kickOn = !this.kickOn; return !this.kickOn; }
    const tr = this.tracks[k];
    tr.muted = !tr.muted;
    return tr.muted;
  }

  /* ----------------------------- private ---------------------------- */
  #pickScale() {
    const list = this.availableScales();
    let s;
    do { s = pick(list); } while (list.length > 1 && this.ctx && s.key === this.ctx.scale.key);
    return s;
  }
  // A lane keeps its length and, once you have set it, its gate across rerolls.
  #genTrack(k, used) {
    const R = ROLE[k], old = this.tracks[k];
    const len = old ? old.len : Math.min(this.steps, MAXL);
    const r = makeRhythm(len, this.rnd / 100, used);
    const tr = {
      len, gates: r.gates, src: r.src, edited: false, muted: old ? old.muted : false,
      gate: old && old.gateSet ? old.gate : randGate(R), gateSet: !!(old && old.gateSet),
      notes: Array(MAXL).fill(null), vel: Array(MAXL).fill(0), dur: Array(MAXL).fill(1),
    };
    this.tracks[k] = tr;
    genNotes(k, tr, this.ctx, this.harmony, this.refs(), this.steps);
    return tr;
  }
  #pickNoteAt(k, i) {
    const tr = this.tracks[k], R = ROLE[k], L = tr.len, pool = poolFor(this.ctx, R.lo, R.hi);
    let prev = null, next = null;
    for (let d = 1; d < L && !prev; d++) { const j = (i - d + L) % L; if (isNote(tr, j)) prev = tr.notes[j]; }
    for (let d = 1; d < L && !next; d++) { const j = (i + d) % L; if (isNote(tr, j)) next = tr.notes[j]; }
    const ws = noteWeights(k, pool, { occ: occ(i, L, this.steps), prev, lastLeap: 0, next, isFirst: !prev, refs: this.refs() }, this.harmony, this.ctx);
    tr.notes[i] = wpick(pool, ws.map(w => Math.pow(w, R.tau)));
    tr.vel[i] = clamp(.7 + .3 * BEAT[i % 16], .45, 1);
  }
}

import { near } from "../core/util.js";
import { ROLE } from "../sequencer/roles.js";
import { gapAhead, isNote } from "../sequencer/timeline.js";
import { asciiName, pcName } from "../theory/spelling.js";

// Exporter: the session as a Coypu (Pharo) script.

const fmtNote = m => (near(m, Math.round(m)) ? String(Math.round(m)) : String(Math.round(m * 100) / 100));
const fmtNum = x => String(Math.round(x * 100) / 100);

// Notes of a lane over `span` steps as Coypu plays them: one entry per trig, with its length
// cut at the next trig. Coypu loops each sequencer on its own size with no pattern restart, so a
// lane whose length does not divide the pattern is written out over the whole pattern.
function laneEvents(tr, span) {
  const ev = [];
  for (let g = 0; g < span; g++) {
    const i = g % tr.len;
    if (isNote(tr, i)) ev.push({ g, m: tr.notes[i].m, d: Math.min(tr.dur[i] || 1, gapAhead(tr, g, span)) });
  }
  return ev;
}

export function coypuCode(session) {
  const M = session.steps, ctx = session.ctx;
  const L = [];
  L.push(`"Scale Dice: ${asciiName(pcName(ctx.root))} ${ctx.scale.key} (Scale.${ctx.scale.key}), ${session.bpm} bpm, ${M}-step pattern. Rename the track keys to your instruments. durations: are in steps, gateTimes: is the share of each duration that sounds."`);
  L.push("p := Performance uniqueInstance.");
  L.push(`p freq: ${session.bpm} bpm.`);
  if (session.kickOn) L.push(`${M} downbeats to: #kick.`);
  session.tracks.forEach((tr, k) => {
    const n = tr.len, fits = M % n === 0, span = fits ? n : M, key = ROLE[k].key;
    const ev = laneEvents(tr, span);
    if (!ev.length) { L.push(`"${key}: no notes"`); return; }
    const gates = Array.from({ length: span }, (_, g) => (isNote(tr, g % n) ? 1 : 0));
    const rhythm = fits && tr.src.kind === "world" && !tr.edited ? `${n} ${tr.src.name}` : `#(${gates.join(" ")}) asSeq`;
    const why = fits ? "" : ` "${n} steps written out to ${M}, so it restarts with the pattern"`;
    L.push(`${tr.muted ? '"muted" ' : ""}((${rhythm} durations: #(${ev.map(e => e.d).join(" ")})) gateTimes: ${fmtNum(tr.gate)}) notes: #(${ev.map(e => fmtNote(e.m)).join(" ")}) to: #${key}.${why}`);
  });
  L.push("p playFor: 16 bars.");
  return L.join("\n");
}

import { clamp, near } from "../core/util.js";
import { SCALES } from "../data/scales.js";
import { buildCtx } from "../theory/scale-context.js";
import { chordOn, makeHarmony } from "../theory/chords.js";
import { poolFor } from "../sequencer/melody.js";
import { ROLE, roundGate } from "../sequencer/roles.js";
import { MASTERS, MAXL, MINL, barsOf, gapIn, isNote } from "../sequencer/timeline.js";

// Memento: the session as plain JSON (pitches instead of object references), and back.

export function snapshot(session) {
  if (!session.ctx) return {};
  return {
    v: 2, scale: session.ctx.scale.key, rootPc: session.ctx.rootPc, steps: session.steps, bpm: session.bpm, rnd: session.rnd,
    micro: session.micro, kick: session.kickOn, harmony: session.harmony.map(c => c.j),
    tracks: session.tracks.map(t => ({ len: t.len, gates: t.gates, notes: t.notes.map(n => (n ? n.m : null)), vel: t.vel, dur: t.dur, src: t.src, edited: t.edited, muted: t.muted, gate: t.gate, gateSet: t.gateSet })),
  };
}

export const canRestore = d => !!(d && (d.v === 1 || d.v === 2));

// v1 (16/32 steps, no lengths or durations) loads too: every lane gets the pattern length and
// each note is held until the next one, up to its role's hold, as v1 played it.
export function restore(session, d) {
  try {
    const sc = SCALES.find(s => s.key === d.scale);
    if (!sc || !Array.isArray(d.tracks) || d.tracks.length !== 3) return false;
    const v1 = d.v === 1;
    session.steps = MASTERS.includes(+d.steps) ? +d.steps : 16;
    session.bpm = clamp(+d.bpm || 124, 70, 170);
    session.rnd = clamp(+d.rnd || 0, 0, 100);
    session.micro = d.micro !== false;
    session.kickOn = d.kick !== false;
    session.ctx = buildCtx(sc, (d.rootPc | 0) % 12);
    const nb = barsOf(session.steps), hj = Array.isArray(d.harmony) ? d.harmony : [];
    session.harmony = hj.length === nb && hj.every(j => j >= 0 && j < session.ctx.asc.length) ? hj.map(j => chordOn(session.ctx, j)) : makeHarmony(session.ctx, nb);
    const pad = (a, f) => Array.from({ length: MAXL }, (_, i) => (Array.isArray(a) && a[i] != null ? a[i] : f));
    session.tracks = d.tracks.map((t, k) => {
      const pool = poolFor(session.ctx, ROLE[k].lo, ROLE[k].hi);
      const tr = {
        len: clamp((v1 ? session.steps : +t.len) || 16, MINL, MAXL),
        gates: pad(t.gates, 0).map(g => (g ? 1 : 0)),
        notes: pad(t.notes, null).map(m => (m == null ? null : pool.find(p => near(p.m, m)) || null)),
        vel: pad(t.vel, .85).map(Number), dur: pad(v1 ? null : t.dur, 0).map(Number),
        src: t.src && typeof t.src === "object" ? t.src : { kind: "random", prob: 50 }, edited: !!t.edited, muted: !!t.muted,
        gate: roundGate(+(v1 ? t.gateFrac : t.gate) || .8), gateSet: !!t.gateSet,
      };
      tr.gates.forEach((g, i) => { if (isNote(tr, i) && !(tr.dur[i] >= 1)) tr.dur[i] = Math.min(gapIn(tr, i), ROLE[k].hold); });
      return tr;
    });
    return true;
  } catch (e) { return false; }
}

// Shared by the scheduler and the MIDI output.
export const LOOKAHEAD = .12;        // seconds scheduled ahead of currentTime
export const TICK_MS = 25;           // how often the scheduler wakes up
export const mtof = m => 440 * Math.pow(2, (m - 69) / 12);

import { mtof } from "./timing.js";

// Strategy: one voice per lane, all with the signature (ac, out, t, m, dur, vel).
// Each builds its own short-lived nodes into `out` and frees them when they end.

function cleanup(src, ...rest) { src.onended = () => { src.disconnect(); rest.forEach(n => n.disconnect()); }; }

function saw(c, out, t, m, dur, vel) {
  const f = mtof(m), end = t + Math.max(.03, dur);
  const o = c.createOscillator(), lp = c.createBiquadFilter(), g = c.createGain();
  o.type = "sawtooth"; o.frequency.setValueAtTime(f, t);
  lp.type = "lowpass"; lp.Q.value = 7;
  lp.frequency.setValueAtTime(Math.min(9000, 250 + f * (5 + 9 * vel)), t);
  lp.frequency.exponentialRampToValueAtTime(Math.max(120, f * 1.6), t + .09 + dur * .5);
  const pk = .5 * vel;
  g.gain.setValueAtTime(0, t);
  g.gain.linearRampToValueAtTime(pk, t + .004);
  g.gain.setTargetAtTime(pk * .75, t + .004, .12);
  g.gain.setTargetAtTime(0, end, .012);
  o.connect(lp); lp.connect(g); g.connect(out);
  o.start(t); o.stop(end + .1);
  cleanup(o, lp, g);
}

function square(c, out, t, m, dur, vel) {
  const f = mtof(m), end = t + Math.max(.03, dur);
  const o = c.createOscillator(), lp = c.createBiquadFilter(), g = c.createGain();
  o.type = "square"; o.frequency.setValueAtTime(f, t);
  lp.type = "lowpass"; lp.Q.value = 1.2;
  lp.frequency.setValueAtTime(Math.min(9000, f * 8 + 1200 * vel), t);
  lp.frequency.exponentialRampToValueAtTime(Math.max(400, f * 3), t + .25);
  const pk = .17 * vel;
  g.gain.setValueAtTime(0, t);
  g.gain.linearRampToValueAtTime(pk, t + .005);
  g.gain.setTargetAtTime(pk * .6, t + .005, .09);
  g.gain.setTargetAtTime(0, end, .02);
  o.connect(lp); lp.connect(g); g.connect(out);
  o.start(t); o.stop(end + .15);
  cleanup(o, lp, g);
}

function tri(c, out, t, m, dur, vel) {
  const f = mtof(m), end = t + Math.max(.04, dur);
  const o = c.createOscillator(), g = c.createGain();
  o.type = "triangle"; o.frequency.setValueAtTime(f, t);
  const pk = .42 * vel;
  g.gain.setValueAtTime(0, t);
  g.gain.linearRampToValueAtTime(pk, t + .008);
  g.gain.setTargetAtTime(pk * .7, t + .008, .25);
  g.gain.setTargetAtTime(0, end, .045);
  if (dur > .22) {                                                  // delayed vibrato on long notes
    const lfo = c.createOscillator(), lg = c.createGain();
    lfo.frequency.value = 5.4;
    lg.gain.setValueAtTime(0, t);
    lg.gain.linearRampToValueAtTime(9, t + Math.min(.3, dur));
    lfo.connect(lg); lg.connect(o.detune);
    lfo.start(t); lfo.stop(end + .3);
    cleanup(lfo, lg);
  }
  o.connect(g); g.connect(out);
  o.start(t); o.stop(end + .3);
  cleanup(o, g);
}

// in the order of ROLE: Saw, Square, Tri
export const VOICES = [saw, square, tri];

// The kick: a pitched sine with a noise click, ducking the synth bus. bus: {kick, synth, noise}
export function kick(c, bus, t, accent) {
  const o = c.createOscillator(), g = c.createGain();
  o.type = "sine";
  o.frequency.setValueAtTime(165, t);
  o.frequency.exponentialRampToValueAtTime(52, t + .07);
  o.frequency.exponentialRampToValueAtTime(42, t + .35);
  g.gain.setValueAtTime(0, t);
  g.gain.linearRampToValueAtTime(accent, t + .002);
  g.gain.setTargetAtTime(0, t + .05, .1);
  o.connect(g); g.connect(bus.kick);
  o.start(t); o.stop(t + .9);
  cleanup(o, g);
  const n = c.createBufferSource(), hp = c.createBiquadFilter(), ng = c.createGain();
  n.buffer = bus.noise; hp.type = "highpass"; hp.frequency.value = 3000; ng.gain.value = .18 * accent;
  n.connect(hp); hp.connect(ng); ng.connect(bus.kick);
  n.start(t);
  cleanup(n, hp, ng);
  const sg = bus.synth.gain;                                        // sidechain-style duck
  sg.cancelScheduledValues(t);
  sg.setTargetAtTime(.5, t, .004);
  sg.setTargetAtTime(1, t + .04, .09);
}

import { VOICES, kick } from "./voices.js";

// Facade over the Web Audio graph: the AudioContext is created lazily on the first user gesture,
// and callers only ever say "play voice k", "mute lane k", "set the delay".
//
//   voices -> track gain k -> panner -> synth bus (ducked) -> master -> compressor -> out
//                          \-> send -> dotted-8th delay -> synth bus
//   kick   -> kick bus -> master
export class AudioEngine {
  ctx = null;
  #nodes = null;

  get ready() { return !!(this.ctx && this.#nodes); }
  get currentTime() { return this.ctx.currentTime; }

  // Resolves true once the context runs. `muted` and `stepDuration` set up a graph built now.
  ensure({ muted = [], stepDuration } = {}) {
    try {
      if (!this.ctx) {
        const Ctor = window.AudioContext || window.webkitAudioContext;
        if (!Ctor) return Promise.resolve(false);
        try { if (navigator.audioSession) navigator.audioSession.type = "playback"; } catch (e) { /* iOS ringer switch */ }
        this.ctx = new Ctor({ latencyHint: "interactive" });
        this.#build(muted, stepDuration);
      }
      const AC = this.ctx;
      const b = AC.createBuffer(1, 1, AC.sampleRate), s = AC.createBufferSource();   // iOS unlock
      s.buffer = b; s.connect(AC.destination); s.start(0);
      if (AC.state === "running") return Promise.resolve(true);
      return AC.resume().then(() => AC.state === "running", () => false);
    } catch (e) { return Promise.resolve(false); }
  }

  playVoice(k, t, m, dur, vel) { VOICES[k](this.ctx, this.#nodes.tracks[k], t, m, dur, vel); }
  playKick(t, accent) { kick(this.ctx, this.#nodes, t, accent); }

  setDelayTime(stepDuration) {
    if (this.ready) this.#nodes.dly.delayTime.setTargetAtTime(Math.min(1.9, stepDuration * 3), this.ctx.currentTime, .05);   // dotted 8th
  }
  setTrackMuted(k, muted) {
    if (this.ready) this.#nodes.tracks[k].gain.setTargetAtTime(muted ? 0 : 1, this.ctx.currentTime, .012);
  }

  // context time that is coming out of the speakers right now
  audibleTime() {
    const AC = this.ctx;
    if (AC.getOutputTimestamp) {
      const ts = AC.getOutputTimestamp();
      if (ts && ts.contextTime > 0 && ts.performanceTime > 0) return ts.contextTime + (performance.now() - ts.performanceTime) / 1000;
    }
    return AC.currentTime - (AC.outputLatency || AC.baseLatency || 0);
  }
  outputTimestamp() { return this.ctx.getOutputTimestamp ? this.ctx.getOutputTimestamp() : null; }
  outputLatency() { return this.ctx.outputLatency || this.ctx.baseLatency || 0; }

  #build(muted, stepDuration) {
    const c = this.ctx;
    const comp = c.createDynamicsCompressor();
    comp.threshold.value = -12; comp.knee.value = 10; comp.ratio.value = 4; comp.attack.value = .004; comp.release.value = .2;
    const master = c.createGain(); master.gain.value = .8;
    master.connect(comp); comp.connect(c.destination);
    const synth = c.createGain(); synth.connect(master);             // ducked by the kick
    const kickBus = c.createGain(); kickBus.gain.value = .95; kickBus.connect(master);
    const dly = c.createDelay(2), fb = c.createGain(), dlp = c.createBiquadFilter(), wet = c.createGain();
    fb.gain.value = .32; dlp.type = "lowpass"; dlp.frequency.value = 2600; wet.gain.value = .5;
    dly.connect(dlp); dlp.connect(fb); fb.connect(dly); dlp.connect(wet); wet.connect(synth);
    const pans = [0, -.22, .22], sends = [0, .2, .28];
    const tracks = VOICES.map((_, k) => {
      const g = c.createGain();
      g.gain.value = muted[k] ? 0 : 1;
      let out = g;
      if (c.createStereoPanner) { const p = c.createStereoPanner(); p.pan.value = pans[k]; g.connect(p); out = p; }
      out.connect(synth);
      if (sends[k]) { const s = c.createGain(); s.gain.value = sends[k]; g.connect(s); s.connect(dly); }
      return g;
    });
    const nb = c.createBuffer(1, Math.floor(c.sampleRate * .02), c.sampleRate), d = nb.getChannelData(0);
    for (let i = 0; i < d.length; i++) d[i] = (Math.random() * 2 - 1) * (1 - i / d.length);
    this.#nodes = { synth, kick: kickBus, dly, tracks, noise: nb };
    if (stepDuration) this.setDelayTime(stepDuration);
  }
}

import { TICK_MS } from "./timing.js";

// Calls `fn` every TICK_MS while running. A worker keeps ticking when the main thread is busy or
// throttled (background tab); setInterval is the fallback when workers are unavailable.
export function createTicker(fn) {
  let worker = null, id = null, running = false;
  const startInterval = () => { clearInterval(id); id = setInterval(fn, TICK_MS); };
  try {
    const src = `let id=null;onmessage=e=>{clearInterval(id);if(e.data==='start')id=setInterval(()=>postMessage(0),${TICK_MS})}`;
    worker = new Worker(URL.createObjectURL(new Blob([src], { type: "text/javascript" })));
    worker.onmessage = fn;
    worker.onerror = () => { worker = null; if (running) startInterval(); };
  } catch (e) { worker = null; }
  return {
    start() { running = true; if (worker) worker.postMessage("start"); else startInterval(); },
    stop() { running = false; if (worker) worker.postMessage("stop"); clearInterval(id); },
  };
}

import { Emitter } from "../core/emitter.js";
import { gapAhead, isNote } from "../sequencer/timeline.js";
import { createTicker } from "./ticker.js";
import { LOOKAHEAD } from "./timing.js";

// Play/stop and the lookahead scheduler: reads the session step by step and sends each step to
// the audio engine and the MIDI output ahead of time.
//
// Events: "state" (playing: boolean), "playhead" (pattern step heard now, -1 when stopped),
//         "notice" (message for the user).
export class Transport extends Emitter {
  #playing = false;
  #nextT = 0;          // context time of the next step to schedule
  #stepIdx = 0;        // pattern step to schedule next
  #vq = [];            // scheduled steps for the playhead {i, t}
  #ticker;

  constructor({ session, audio, midi }) {
    super();
    this.session = session;
    this.audio = audio;
    this.midi = midi;
    this.#ticker = createTicker(() => this.#schedule());
  }

  get playing() { return this.#playing; }

  toggle() { return this.#playing ? this.stop() : this.start(); }

  async start() {
    const { session, audio, midi } = this;
    const ok = await audio.ensure({ muted: session.tracks.map(t => t.muted), stepDuration: session.stepDuration });
    if (!ok) { this.emit("notice", "Audio is blocked here. Tap Play again."); return; }
    if (midi.out || midi.sync) await midi.settle();
    midi.resetTimebase();                                             // fresh audio-to-MIDI offset: it is not tracked while stopped
    this.#playing = true; this.#stepIdx = 0; this.#vq.length = 0;
    this.#nextT = Math.max(audio.currentTime + .05, this.#nextT);     // a quick restart waits for the steps already scheduled
    this.#ticker.start(); this.#schedule(); requestAnimationFrame(this.#frame);
    this.emit("state", true);
  }

  stop() {
    this.#playing = false; this.#ticker.stop(); this.#vq.length = 0;
    this.emit("playhead", -1);
    this.emit("state", false);
    this.midi.clockStop();
    this.midi.drain(() => this.#playing);
  }

  // the pattern got shorter: keep the next step inside it
  wrap(steps) { this.#stepIdx %= steps; }

  // g: step in the pattern. Each lane reads its own step g % len; a note sounds for its duration
  // (cut at the lane's next note, also across the pattern restart) times the lane's gate, as in Coypu.
  #playStep(g, t) {
    const { session, audio, midi } = this, M = session.steps, sd = session.stepDuration;
    if (midi.sync) midi.clockTicks(g, t, sd);
    if (session.kickOn && g % 4 === 0) audio.playKick(t, g % 16 === 0 ? 1 : .9);
    session.tracks.forEach((tr, k) => {
      const i = g % tr.len;
      if (!isNote(tr, i)) return;
      const steps = Math.min(tr.dur[i] || 1, gapAhead(tr, g, M));
      const m = tr.notes[i].m, dur = steps * sd * tr.gate, vel = tr.vel[i] || .85;
      if (midi.local) audio.playVoice(k, t, m, dur, vel);
      if (!tr.muted) midi.note(k, m, t, dur, vel);
    });
  }

  #schedule() {
    if (!this.#playing || !this.audio.ctx) return;
    const now = this.audio.currentTime;
    this.midi.timebase();
    if (this.#nextT < now - .05) this.#nextT = now + .03;              // resumed after an interruption
    while (this.#nextT < now + LOOKAHEAD) {
      this.#playStep(this.#stepIdx, this.#nextT);
      this.#vq.push({ i: this.#stepIdx, t: this.#nextT });
      this.#nextT += this.session.stepDuration;
      this.#stepIdx = (this.#stepIdx + 1) % this.session.steps;
    }
    this.midi.flush(now + LOOKAHEAD);
  }

  // the playhead follows what is heard, not what is scheduled
  #frame = () => {
    if (!this.#playing) return;
    this.#schedule();
    const now = this.audio.audibleTime();
    let s = null;
    while (this.#vq.length && this.#vq[0].t <= now) s = this.#vq.shift().i;
    if (s !== null) this.emit("playhead", s);
    requestAnimationFrame(this.#frame);
  };
}

import { Emitter } from "../core/emitter.js";
import { loadPref, savePref } from "../core/storage.js";
import { clamp } from "../core/util.js";
import { LOOKAHEAD } from "../audio/timing.js";

// Saw, Square, Tri go out on MIDI channels 1, 2, 3. Each lane is monophonic on its own
// channel, so microtones (24-TET, Partch JI) ride on a per-note pitch bend.
// MIDI clock (24 ppqn, Start, Stop) has its own port, which can also be the notes port.
export const MIDI_CH = [0, 1, 2];                // 0-based: ch 1, 2, 3
const BEND_RANGE = 2;                            // semitones, also sent to the synth as RPN 0
const MIDI_KEY = "diceTherapy.midiOut";          // last port used
const CLOCK_KEY = "diceTherapy.clockOut";        // last clock port used

// Events: "change" (ports, selection or the local-synth switch changed), "notice" (message).
export class MidiOutput extends Emitter {
  access = null;
  out = null;          // notes port
  sync = null;         // clock port
  local = true;        // also play the built-in synths
  #tb = null;          // audio-to-performance.now() offset, ms
  #tbOk = false;
  #run = false;        // clock: Start sent
  #tickAt = 0;         // time of the last clock
  #stopAt = 0;         // time of the last Stop
  #pend = [null, null, null];
  #bend = [null, null, null];

  constructor(audio) {
    super();
    this.audio = audio;
  }

  get supported() { return !!navigator.requestMIDIAccess; }
  // connected outputs, empty before access is granted
  get outputs() { return this.access ? [...this.access.outputs.values()].filter(o => o.state !== "disconnected") : []; }

  /* ---------------------------- timebase ---------------------------- */
  // Offset from AudioContext time to performance.now() time at which it is heard, so MIDI lands
  // with the audio. The output timestamp is exact; the currentTime fallback moves in audio-callback
  // chunks, so it is smoothed. Switching source or a jump (new output device) snaps it.
  timebase() {
    const ts = this.audio.outputTimestamp();
    const ok = !!(ts && ts.contextTime > 0 && ts.performanceTime > 0);
    const raw = ok ? ts.performanceTime - ts.contextTime * 1000
      : performance.now() - (this.audio.currentTime - this.audio.outputLatency()) * 1000;
    this.#tb = this.#tb == null || ok !== this.#tbOk || Math.abs(raw - this.#tb) > 50 ? raw : this.#tb + (raw - this.#tb) * .02;
    this.#tbOk = ok;
  }
  resetTimebase() { this.#tb = null; }
  // The first output timestamps of a fresh AudioContext are off by up to a buffer while the device
  // primes: before the first notes, wait (~30 ms) until two readings agree
  settle() {
    return new Promise(res => {
      const t0 = performance.now();
      let last = null;
      const poll = () => {
        const ts = this.audio.outputTimestamp();
        if (!ts || ts.contextTime > .5 || performance.now() - t0 > 300) return res();
        if (ts.contextTime > 0 && ts.performanceTime > 0 && (!last || ts.contextTime !== last.c)) {
          const o = ts.performanceTime - ts.contextTime * 1000;
          if (last && Math.abs(o - last.o) < 1) return res();
          last = { c: ts.contextTime, o };
        }
        setTimeout(poll, 4);
      };
      poll();
    });
  }
  #perfAt(t) {
    if (this.#tb == null) this.timebase();
    return this.#tb + t * 1000;
  }
  #send(data, at, port = this.out) {
    try { port.send(data, at); } catch (e) { /* port went away */ }
  }

  /* ------------------------------ notes ----------------------------- */
  note(k, m, t, dur, vel) {
    if (!this.out) return;
    const ch = MIDI_CH[k], n = clamp(Math.round(m), 0, 127), on = this.#perfAt(t), p = this.#pend[k];
    const bend = clamp(Math.round(8192 + (m - n) / BEND_RANGE * 8192), 0, 16383);
    if (p) this.#send([0x80 | ch, p.n, 0], Math.min(this.#perfAt(p.off), on));   // a tempo jump can overlap notes: cut the old one
    if (bend !== this.#bend[k]) { this.#send([0xE0 | ch, bend & 127, bend >> 7], on); this.#bend[k] = bend; }
    this.#send([0x90 | ch, n, clamp(Math.round(vel * 127), 1, 127)], on);
    this.#pend[k] = { n, off: t + dur };
  }
  // note-offs wait here until they fall inside the lookahead, so a later note can still pull them in
  flush(horizon) {
    this.#pend.forEach((p, k) => {
      if (!p || p.off >= horizon) return;
      if (this.out) this.#send([0x80 | MIDI_CH[k], p.n, 0], this.#perfAt(p.off));
      this.#pend[k] = null;
    });
  }
  // after stop, ringing notes still get their note-off when due
  drain(isPlaying) {
    if (isPlaying()) return;
    this.flush(this.audio.currentTime + LOOKAHEAD);
    if (this.#pend.some(Boolean)) setTimeout(() => this.drain(isPlaying), 25);
  }

  /* ------------------------------ clock ----------------------------- */
  // MIDI clock: 6 clocks per 16th step, laid on the step grid with the same lookahead and timestamps
  // as the notes, so tempo changes reach the clock from the next step, like the notes. Start goes
  // just before the first clock, which the other device plays as step 1. Stop goes after the clocks
  // already queued, so the other device stops where the audio does.
  clockTicks(g, t, stepDuration) {
    if (!this.#run) {
      if (g % 16) return;                                             // start, or join while playing, on a bar line
      this.#tickAt = Math.max(this.#perfAt(t) - 1, this.#stopAt + 1); // never before the last Stop
      this.#send([0xFA], this.#tickAt, this.sync);
      this.#run = true;
    }
    const sd = stepDuration / 6;
    for (let n = 0; n < 6; n++) {
      this.#tickAt = Math.max(this.#perfAt(t + n * sd), this.#tickAt); // never out of order
      this.#send([0xF8], this.#tickAt, this.sync);
    }
  }
  clockStop(now) {
    if (!this.#run) return;
    this.#run = false;
    this.#stopAt = now ? performance.now() : Math.max(performance.now(), this.#tickAt + 1);
    if (this.sync) this.#send([0xFC], now ? undefined : this.#stopAt, this.sync);
  }

  /* ------------------------------ ports ----------------------------- */
  setOut(out, remember) {
    out = out || null;
    if (this.out && this.out !== out) this.flush(Infinity);
    this.out = out;
    this.#bend = [null, null, null];
    if (out) MIDI_CH.forEach(ch => { const c = 0xB0 | ch; this.#send([c, 101, 0, c, 100, 0, c, 6, BEND_RANGE, c, 38, 0, c, 101, 127, c, 100, 127]); });
    else if (!this.local) this.local = true;                          // without MIDI, never leave the synths silent
    if (remember) savePref(MIDI_KEY, out ? out.name : "off");
    this.emit("change");
  }
  setClock(out, remember) {
    out = out || null;
    if (this.sync !== out) this.clockStop();                          // the old port stops after the clocks it already has
    this.sync = out;
    if (remember) savePref(CLOCK_KEY, out ? out.name : "off");
    this.emit("change");
  }
  setLocal(on) { this.local = on; }
  // id from a port menu ("" = off)
  portById(id) { return id && this.access ? this.access.outputs.get(id) : null; }

  // Notes: the last port used (waiting for it while unplugged), else the first real one.
  // Clock: only a port picked for it before, or the first real one when connecting from its menu.
  // who: the menu that asked to connect ("out" or "clock"), null when it happens on its own.
  refresh(who) {
    const outs = this.outputs;
    const first = outs.find(o => !/GS Wavetable/i.test(o.name));
    const byName = n => outs.find(o => o.name === n);
    if (this.out && !outs.some(o => o.id === this.out.id)) this.setOut(null);      // unplugged
    if (this.sync && !outs.some(o => o.id === this.sync.id)) this.setClock(null);
    if (!this.out) {
      let last = loadPref(MIDI_KEY);
      if (who === "out" && last === "off") last = null;
      if (who === "clock" && last == null) { last = "off"; savePref(MIDI_KEY, "off"); }   // connecting for clock only keeps the notes off
      const d = last === "off" ? null : !last ? first : byName(last) || (who === "out" ? first : null);
      if (d) this.setOut(d, who === "out");
    }
    if (!this.sync) {
      const last = loadPref(CLOCK_KEY);
      const d = who === "clock" ? byName(last) || first : last && last !== "off" ? byName(last) : null;
      if (d) this.setClock(d, who === "clock");
    }
    this.emit("change");
  }
  async connect(who) {
    try { this.access = await navigator.requestMIDIAccess(); }
    catch (e) {
      if (who) this.emit("notice", "MIDI is blocked: allow it in the site settings");
      this.emit("change");
      return;
    }
    this.access.onstatechange = () => this.refresh(null);
    this.refresh(who);
  }
  // connect without asking when the permission was granted before
  autoConnect() {
    try { navigator.permissions.query({ name: "midi" }).then(s => { if (s.state === "granted") this.connect(null); }, () => {}); }
    catch (e) { /* no Permissions API */ }
  }
  // page is going away: all notes off, Stop right away
  panic() {
    if (this.out) MIDI_CH.forEach(ch => this.#send([0xB0 | ch, 123, 0]));
    this.clockStop(true);
  }
}

export const $ = s => document.querySelector(s);
export const $$ = s => document.querySelectorAll(s);

// replay a one-shot CSS animation class
export function restartAnimation(el, cls) { el.classList.remove(cls); void el.offsetWidth; el.classList.add(cls); }

export const prefersReducedMotion = () => matchMedia("(prefers-reduced-motion: reduce)").matches;

export const ICON = {
  play: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 4v16l14-8z" fill="currentColor"/></svg>',
  stop: '<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="5" y="5" width="14" height="14" fill="currentColor"/></svg>',
  reroll: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="square" stroke-linejoin="miter" aria-hidden="true"><path d="M4 11V6h14"/><path d="M15 3l3 3-3 3"/><path d="M20 13v5H6"/><path d="M9 15l-3 3 3 3"/></svg>',
};

// a plain square face with square pips
const PIPS = [["tl", 28, 28], ["tr", 72, 28], ["ml", 28, 50], ["c", 50, 50], ["mr", 72, 50], ["bl", 28, 72], ["br", 72, 72]];
export const FACES = { 1: ["c"], 2: ["tl", "br"], 3: ["tl", "c", "br"], 4: ["tl", "tr", "bl", "br"], 5: ["tl", "tr", "c", "bl", "br"], 6: ["tl", "tr", "ml", "mr", "bl", "br"] };
export const dieSVG = () => `<svg class="dface" viewBox="0 0 100 100" aria-hidden="true"><rect class="f" x="2" y="2" width="96" height="96"/><g class="p">${PIPS.map(([n, x, y]) => `<rect data-p="${n}" x="${x - 8.5}" y="${y - 8.5}" width="17" height="17"/>`).join("")}</g></svg>`;

import { $, $$, prefersReducedMotion, restartAnimation } from "./dom.js";
import { FACES, dieSVG } from "./icons.js";

const randomFace = () => 1 + Math.floor(Math.random() * 6);

// The two dice buttons (hero and transport bar): faces and the tumble.
export class DieView {
  #rolling = false;

  constructor(selectors = ["#die", "#die2"]) {
    this.els = selectors.map(s => $(s));
    this.els.forEach(el => { el.innerHTML = dieSVG(); });
  }

  onClick(fn) { this.els.forEach(el => el.addEventListener("click", fn)); }

  setFace(n) {
    $$(".dface [data-p]").forEach(c => { c.style.display = FACES[n].includes(c.dataset.p) ? "" : "none"; });
  }

  // Tumble through a few faces, then call `onLanded` and show the final face. Ignored mid-roll.
  roll(onLanded) {
    if (this.#rolling) return;
    this.#rolling = true;
    try { if (navigator.vibrate) navigator.vibrate(18); } catch (e) { /* not supported */ }
    const finish = () => { onLanded(); this.setFace(randomFace()); this.#rolling = false; };
    if (prefersReducedMotion()) { finish(); return; }
    this.els.forEach(el => restartAnimation(el, "rolling"));
    let n = 0;
    const iv = setInterval(() => {
      this.setFace(randomFace());
      if (++n >= 7) { clearInterval(iv); finish(); }
    }, 75);
  }
}

import { PARTCH_R, TUNING } from "../data/tunings.js";
import { harmonyText } from "../theory/chords.js";
import { LET, accStr, pcName } from "../theory/spelling.js";
import { $ } from "./dom.js";

// The current scale: root, name, SuperCollider code, scale tones, tuning and harmony.
export class HeroView {
  constructor(session) { this.session = session; }

  render() {
    const ctx = this.session.ctx, sc = ctx.scale, h = this.session.harmony;
    const acc = accStr(ctx.root.acc);                                  // the accidental set as a superior
    $("#root").innerHTML = LET[ctx.root.L] + (acc ? `<span class="acc">${acc}</span>` : "");
    $("#sname").textContent = sc.name;
    $("#sccode").innerHTML = `Scale.<em>${sc.key}</em> #[${sc.deg.join(", ")}]${sc.desc ? ` / desc #[${sc.desc.join(", ")}]` : ""}`;
    const tones = h[0].tones;
    $("#tones").innerHTML = ctx.degs.map(d => {
      const cls = d.ai === 0 ? "tone r" : tones.has(d.ai) ? "tone c" : d.asc ? "tone" : "tone d";
      const sub = sc.ppo === 43 ? `${PARTCH_R[d.step]}${d.sp.cents ? ` ${d.sp.cents > 0 ? "+" : "−"}${Math.abs(d.sp.cents)}¢` : ""}` : d.asc ? d.step : `${d.step} desc`;
      return `<span class="${cls}"><b>${pcName(d.sp)}</b><small>${sub}</small></span>`;
    }).join("");
    $("#tuning").textContent = `${TUNING[sc.ppo].label} · ${sc.deg.length} notes${sc.desc ? " asc/desc" : ""}`;
    $("#harmony").textContent = harmonyText(ctx, h);
  }
}

import { MIDI_CH } from "../midi/midi-output.js";
import { ROLE } from "../sequencer/roles.js";
import { MAXL, MINL, coverage, effDur, isNote } from "../sequencer/timeline.js";
import { chordLabel } from "../theory/chords.js";
import { noteName } from "../theory/spelling.js";
import { $ } from "./dom.js";
import { ICON } from "./icons.js";

const COLORS = ["var(--saw)", "var(--sqr)", "var(--tri)"];
const RANGE_TXT = ["bass · MIDI 24-48", "mid · MIDI 48-70", "lead · MIDI 62-86"];
const LEN_OPTS = Array.from({ length: MAXL - MINL + 1 }, (_, i) => `<option value="${i + MINL}">${i + MINL}</option>`).join("");
const GATE_OPTS = Array.from({ length: 16 }, (_, i) => { const v = 25 + i * 5; return `<option value="${v / 100}">${v}%</option>`; }).join("");

function srcHTML(tr) {
  const s = tr.src, ed = tr.edited ? " <i>· edited</i>" : "";
  if (s.kind === "world") return `<span class="tag">world</span>${tr.len} ${s.name} <i>· ${s.origin}</i>${ed}`;
  return `<span class="tag">random</span>${tr.len} randomTrigsWithProbability: ${s.prob}${ed}`;
}

function laneHeadHTML(k) {
  if (k < 0) return `<span class="num">K</span><span class="lname">Kick<small>4/4 · sine</small></span><button type="button" class="ib mute" aria-label="Mute kick">M</button><code class="src"></code>`;
  const nm = ROLE[k].name;
  return `<span class="num">${k + 1}</span><span class="lname">${nm}<small>${RANGE_TXT[k]} · ch ${MIDI_CH[k] + 1}</small></span><button type="button" class="ib mute" aria-label="Mute ${nm}">M</button><button type="button" class="ib reroll" aria-label="Reroll the ${nm} track">${ICON.reroll}</button>` +
    `<div class="lctl"><span class="grp"><span class="lbl">Steps</span><span class="stepper"><button type="button" class="ib sm" data-len="-1" aria-label="${nm}: one step shorter">−</button>` +
    `<select class="sel len" aria-label="${nm} length in steps">${LEN_OPTS}</select><button type="button" class="ib sm" data-len="1" aria-label="${nm}: one step longer">+</button></span></span>` +
    `<span class="grp g"><span class="lbl">Gate</span><select class="sel gate" aria-label="${nm} gate time">${GATE_OPTS}</select></span></div><code class="src"></code>`;
}

// The sequencer: the kick lane (k = -1) and one lane per synth (k = 0..2).
// Lane index li = k + 1 in the per-lane arrays.
export class LanesView {
  #cells = [];         // cells per lane (kick first)
  #heads = [];         // each lane's playhead step

  constructor(session, host = $("#lanes")) {
    this.session = session;
    this.host = host;
  }

  // the pattern step the kick lane shows, -1 when none
  get patternStep() { return this.#heads[0] >= 0 ? this.#heads[0] : -1; }

  render() {
    const host = this.host;
    host.textContent = "";
    this.#cells = []; this.#heads = [];
    for (let k = -1; k < ROLE.length; k++) {
      const lane = document.createElement("div");
      lane.className = "lane" + (k < 0 ? " kick" : "");
      lane.dataset.k = k;
      lane.style.setProperty("--c", k < 0 ? "var(--kick)" : COLORS[k]);
      const head = document.createElement("div");
      head.className = "lh";
      head.innerHTML = laneHeadHTML(k);
      lane.appendChild(head);
      const grid = document.createElement("div");
      grid.className = "grid";
      lane.appendChild(grid);
      host.appendChild(lane);
      this.#cells.push([]);
      this.#heads.push(-1);
      this.fillGrid(k);
    }
  }

  // (re)build a lane's cells: the kick shows the whole pattern with the chord of each bar,
  // a synth lane shows its own length, in bars of 16 and beats of 4
  fillGrid(k) {
    const lane = this.host.querySelector(`.lane[data-k="${k}"]`);
    if (!lane) return;
    const s = this.session;
    const grid = lane.querySelector(".grid"), M = s.steps, n = k < 0 ? M : s.tracks[k].len;
    const labels = k < 0 ? s.harmony.map(c => chordLabel(s.ctx, c)) : null;
    grid.textContent = "";
    const cells = [];
    for (let b = 0; b < Math.ceil(n / 16); b++) {
      const bar = document.createElement("div");
      bar.className = "bar";
      if (k < 0) {
        const cap = document.createElement("div");
        cap.className = "cap";
        cap.innerHTML = M > 16 ? `Bar ${b + 1} · <b>${labels[b]}</b>` : `Chord · <b>${labels[0]}</b>`;
        bar.appendChild(cap);
      }
      for (let q = 0; q < 4 && b * 16 + q * 4 < n; q++) {
        const beat = document.createElement("div");
        beat.className = "beat";
        for (let j = 0; j < 4; j++) {
          const i = b * 16 + q * 4 + j;
          if (i >= n) break;
          const cell = document.createElement(k < 0 ? "span" : "button");
          cell.className = "cell" + (i % 4 === 0 ? " bt" : "");
          if (k >= 0) { cell.type = "button"; cell.dataset.i = i; }
          beat.appendChild(cell);
          cells.push(cell);
        }
        bar.appendChild(beat);
      }
      grid.appendChild(bar);
    }
    this.#cells[k + 1] = cells;
    this.#heads[k + 1] = -1;
    this.updateLane(k);
  }

  updateLane(k) {
    const cells = this.#cells[k + 1];
    if (!cells || !cells.length) return;
    const s = this.session, lane = cells[0].closest(".lane"), M = s.steps;
    if (k < 0) {
      cells.forEach((c, i) => c.classList.toggle("on", i % 4 === 0));
      lane.classList.toggle("muted", !s.kickOn);
      lane.querySelector(".mute").setAttribute("aria-pressed", String(!s.kickOn));
      lane.querySelector(".src").innerHTML = `<span class="tag">4/4</span>${M} downbeats`;
      return;
    }
    const tr = s.tracks[k], R = ROLE[k], cov = coverage(tr);
    const label = n => noteName(n.m, n.d.sp);
    cells.forEach((c, i) => {
      const on = isNote(tr, i), own = on ? -1 : cov.owner[i], out = i >= M ? " (past the pattern end, not played)" : "";
      c.classList.toggle("on", on);
      c.classList.toggle("tail", own >= 0);
      c.classList.toggle("end", own >= 0 && cov.end[i]);
      c.classList.toggle("out", i >= M);
      if (on) {
        const n = tr.notes[i], nm = label(n), ct = n.d.sp.cents, d = effDur(tr, i);
        c.innerHTML = `<span class="nn">${nm}</span>${ct ? `<span class="ct">${ct > 0 ? "+" : "−"}${Math.abs(ct)}¢</span>` : ""}`;
        c.setAttribute("aria-label", `${R.name} step ${i + 1}: ${nm}, ${d} step${d > 1 ? "s" : ""}${out}`);
      } else if (own >= 0) {
        c.innerHTML = "";
        c.setAttribute("aria-label", `${R.name} step ${i + 1}: ${label(tr.notes[own])} held${out}`);
      } else {
        c.innerHTML = i % 4 === 0 ? `<span class="st">${i + 1}</span>` : "";
        c.setAttribute("aria-label", `${R.name} step ${i + 1}: off${out}`);
      }
    });
    lane.classList.toggle("muted", tr.muted);
    lane.querySelector(".mute").setAttribute("aria-pressed", String(tr.muted));
    lane.querySelector(".src").innerHTML = srcHTML(tr);
    lane.querySelector(".sel.len").value = String(tr.len);
    lane.querySelector(".sel.gate").value = String(tr.gate);
    lane.querySelector('[data-len="-1"]').disabled = tr.len <= MINL;
    lane.querySelector('[data-len="1"]').disabled = tr.len >= MAXL;
  }

  // g: pattern step, -1 clears. The kick lane shows g, each synth lane its own step g % len.
  setPlayhead(g) {
    const s = this.session;
    this.#cells.forEach((cells, li) => {
      const old = this.#heads[li];
      if (old >= 0 && cells[old]) cells[old].classList.remove("now");
      const i = g >= 0 && g < s.steps ? (li === 0 ? g : g % s.tracks[li - 1].len) : -1;
      this.#heads[li] = i;
      if (i >= 0 && cells[i]) cells[i].classList.add("now");
    });
  }
}

import { dragDur, effDur, ownerOf } from "../sequencer/timeline.js";

// Input controller for the sequencer lanes (event delegation on the lanes host).
// Step edits go straight to the session and redraw one lane; everything that reaches beyond the
// lanes (mute, reroll, lane length) is handed to `actions`.
//
// actions: { toggleMute(k), rerollTrack(k, button), setTrackLen(k, n), setGate(k, v) }
export class LaneInput {
  #drag = null;        // pointer press on a step, becomes a duration drag once it moves
  #lastPtr = 0;        // when and where the last pointer tap ended, to drop the click that follows
  #lastPtrCell = null;

  constructor({ session, view, actions }) {
    this.session = session;
    this.view = view;
    this.actions = actions;
    this.host = view.host;
  }

  bind() {
    const host = this.host;
    host.addEventListener("click", this.#onClick);
    host.addEventListener("change", this.#onChange);
    // Tap a step to switch it. Press on a note (or a step it holds) and drag to set its length.
    host.addEventListener("pointerdown", this.#onPointerDown);
    addEventListener("pointermove", this.#onPointerMove);
    addEventListener("pointerup", this.#onPointerUp);
    addEventListener("pointercancel", e => { if (this.#drag && e.pointerId === this.#drag.id) this.#drag = null; });
    host.addEventListener("contextmenu", e => { if (e.target.closest("button.cell")) e.preventDefault(); });
    host.addEventListener("keydown", this.#onKeyDown);
  }

  #toggleStep(k, i) {
    this.session.toggleStep(k, i);
    this.view.updateLane(k);
  }
  #setDur(k, own, d) {
    if (this.session.setDur(k, own, d)) this.view.updateLane(k);
  }

  #onClick = e => {
    const lane = e.target.closest(".lane");
    if (!lane) return;
    const k = +lane.dataset.k;
    if (e.target.closest(".mute")) { this.actions.toggleMute(k); return; }
    const rr = e.target.closest(".reroll");
    if (rr) { this.actions.rerollTrack(k, rr); return; }
    const lb = e.target.closest("[data-len]");
    if (lb && k >= 0) { this.actions.setTrackLen(k, this.session.tracks[k].len + +lb.dataset.len); return; }
    // steps: pointers act on pointerup below; a click with detail 0 comes from the keyboard
    const cell = e.target.closest("button.cell");
    if (cell && k >= 0 && e.detail === 0 && !(cell === this.#lastPtrCell && performance.now() - this.#lastPtr < 500)) this.#toggleStep(k, +cell.dataset.i);
  };

  #onChange = e => {
    const lane = e.target.closest(".lane");
    if (!lane || +lane.dataset.k < 0) return;
    const k = +lane.dataset.k;
    if (e.target.matches(".sel.len")) this.actions.setTrackLen(k, +e.target.value);
    else if (e.target.matches(".sel.gate")) this.actions.setGate(k, +e.target.value);
  };

  #cellAt(x, y) {
    const el = document.elementFromPoint(x, y);
    return el && el.closest ? el.closest("#lanes button.cell") : null;
  }

  #onPointerDown = e => {
    if (e.button > 0) return;
    const cell = e.target.closest("button.cell");
    if (!cell) return;
    const k = +cell.closest(".lane").dataset.k, i = +cell.dataset.i;
    this.#drag = { k, i, cell, own: ownerOf(this.session.tracks[k], i), id: e.pointerId, x: e.clientX, y: e.clientY, moved: false };
  };

  #onPointerMove = e => {
    const drag = this.#drag;
    if (!drag || e.pointerId !== drag.id) return;
    if (!drag.moved) {
      if (Math.abs(e.clientX - drag.x) + Math.abs(e.clientY - drag.y) < 8) return;
      if (drag.own < 0) { this.#drag = null; return; }                 // a swipe from an empty step is not ours
      drag.moved = true;
    }
    const cell = this.#cellAt(e.clientX, e.clientY);
    if (!cell || +cell.closest(".lane").dataset.k !== drag.k) return;
    const tr = this.session.tracks[drag.k];
    this.#setDur(drag.k, drag.own, dragDur(tr, drag.own, +cell.dataset.i));
  };

  #onPointerUp = e => {
    const d = this.#drag;
    if (!d || e.pointerId !== d.id) return;
    this.#drag = null;
    this.#lastPtr = performance.now();
    this.#lastPtrCell = d.cell;
    if (!d.moved) this.#toggleStep(d.k, d.i);
  };

  // Shift + arrows on a focused note or held step: one step longer or shorter
  #onKeyDown = e => {
    if (!e.shiftKey || (e.key !== "ArrowRight" && e.key !== "ArrowLeft")) return;
    const cell = e.target.closest("button.cell");
    if (!cell) return;
    const k = +cell.closest(".lane").dataset.k, tr = this.session.tracks[k], own = ownerOf(tr, +cell.dataset.i);
    if (own < 0) return;
    e.preventDefault();
    this.#setDur(k, own, effDur(tr, own) + (e.key === "ArrowRight" ? 1 : -1));
  };
}

import { WORLD } from "../data/rhythms.js";
import { MASTERS } from "../sequencer/timeline.js";
import { $, $$, restartAnimation } from "./dom.js";
import { ICON } from "./icons.js";

// Pattern settings (length, tempo, rhythm source, microtonal) and the transport buttons.
// Reads the session to show it; user input goes to `actions`.
//
// actions: { setMaster(n), setBpm(bpm), setRnd(pct), setMicro(on), togglePlay(), regenerate(), copyCoypu() }
export class ControlsView {
  constructor(session) {
    this.session = session;
    this.regenBtn = $("#regen");
    this.regenBtn.innerHTML = `${ICON.reroll}<span>Regenerate</span>`;
  }

  bind(actions) {
    $("#play").addEventListener("click", actions.togglePlay);
    this.regenBtn.addEventListener("click", actions.regenerate);
    $("#copy").addEventListener("click", actions.copyCoypu);
    $$(".seg button").forEach(b => b.addEventListener("click", () => actions.setMaster(+b.dataset.steps)));
    $("#bpm").addEventListener("input", e => actions.setBpm(+e.target.value));
    $("#rnd").addEventListener("input", e => actions.setRnd(+e.target.value));
    $("#micro").addEventListener("change", e => actions.setMicro(e.target.checked));
  }

  sync() {
    const s = this.session;
    MASTERS.forEach(n => $("#s" + n).setAttribute("aria-checked", String(s.steps === n)));
    $("#bpm").value = s.bpm;
    this.showBpm();
    $("#rnd").value = s.rnd;
    $("#rndOut").textContent = `${s.rnd}% random · ${100 - s.rnd}% world`;
    $("#micro").checked = s.micro;
    const n = s.availableScales().length;
    $("#meta").innerHTML = `<span>${n} SC scales ·</span> <span>${WORLD.length} Coypu rhythms</span>`;
  }

  showBpm() { $("#bpmOut").textContent = `${this.session.bpm} BPM`; }

  setPlaying(playing) {
    const b = $("#play");
    b.setAttribute("aria-pressed", String(playing));
    b.innerHTML = playing ? `${ICON.stop}<span>Stop</span>` : `${ICON.play}<span>Play</span>`;
  }

  spinRegen() { restartAnimation(this.regenBtn, "spin"); }
}

import { $ } from "./dom.js";

// The MIDI out / Clock out menus and the local-synths switch. Observes the MidiOutput and redraws
// from it on every change; user choices go back to it.
export class MidiPanel {
  constructor(midi) {
    this.midi = midi;
    this.outSel = $("#midiOut");
    this.clockSel = $("#clockOut");
    this.local = $("#local");
    this.localRow = $("#localRow");
  }

  bind() {
    const midi = this.midi;
    midi.on("change", () => this.render());
    if (!midi.supported) { this.render(); return; }
    [this.outSel, this.clockSel].forEach((sel, i) => {
      sel.addEventListener("change", () => {
        if (sel.value === "?") { midi.connect(i ? "clock" : "out"); return; }
        const port = midi.portById(sel.value);
        if (i) midi.setClock(port, true); else midi.setOut(port, true);
      });
    });
    this.local.addEventListener("change", e => midi.setLocal(e.target.checked));
    this.render();
  }

  render() {
    const midi = this.midi, sels = [[this.outSel, midi.out], [this.clockSel, midi.sync]];
    if (!midi.supported) {
      sels.forEach(([sel]) => { sel.replaceChildren(new Option("Not available in this browser", "")); sel.disabled = true; });
      return;
    }
    const outs = midi.outputs;
    for (const [sel, port] of sels) {
      if (!midi.access) sel.replaceChildren(new Option("Off", ""), new Option("Connect…", "?"));
      else {
        const none = new Option("No MIDI outputs found", "-");
        none.disabled = true;
        sel.replaceChildren(new Option("Off", ""), ...outs.map(o => new Option(o.name, o.id)), ...(outs.length ? [] : [none]));
      }
      sel.value = port ? port.id : "";
    }
    this.local.checked = midi.local;
    this.localRow.hidden = !midi.out;
  }
}

import { $ } from "./dom.js";

// A short status message above the transport.
export class Toast {
  #timer = 0;
  constructor(el = $("#toast")) { this.el = el; }

  show(msg) {
    this.el.textContent = msg;
    this.el.classList.add("show");
    clearTimeout(this.#timer);
    this.#timer = setTimeout(() => this.el.classList.remove("show"), 1700);
  }
}

import { $ } from "./dom.js";

// The Coypu code dialog, for when the clipboard is not available.
export class CodeModal {
  constructor() {
    this.el = $("#modal");
    this.text = $("#mtext");
  }

  bind() {
    $("#mclose").addEventListener("click", () => this.close());
    $("#msel").addEventListener("click", () => this.#selectAll());
    this.el.addEventListener("click", e => { if (e.target.id === "modal") this.close(); });
  }

  open(txt) {
    this.text.value = txt;
    this.el.classList.add("open");
    this.#selectAll();
  }

  close() { this.el.classList.remove("open"); }

  #selectAll() { this.text.focus(); this.text.select(); }
}

// Global keys: Space play/stop, D roll, R regenerate, Escape closes the dialog.
// actions: { togglePlay(), roll(), regenerate(), closeModal() }
export function bindShortcuts(actions) {
  const typing = e => e.target.matches("input, textarea, select");
  document.addEventListener("keydown", e => {
    if (typing(e) || e.metaKey || e.ctrlKey || e.altKey) return;
    if (e.key === "Escape") { actions.closeModal(); return; }
    if (e.code === "Space") { e.preventDefault(); if (!e.repeat) actions.togglePlay(); }
    else if (e.key === "d" || e.key === "D") actions.roll();
    else if (e.key === "r" || e.key === "R") actions.regenerate();
  });
  document.addEventListener("keyup", e => { if (e.code === "Space" && !typing(e)) e.preventDefault(); });
}

import { AudioEngine } from "./audio/engine.js";
import { Transport } from "./audio/transport.js";
import { coypuCode } from "./export/coypu.js";
import { MidiOutput } from "./midi/midi-output.js";
import { canRestore, restore, snapshot } from "./persistence/snapshot.js";
import { Session } from "./sequencer/session.js";
import { CodeModal } from "./ui/code-modal.js";
import { ControlsView } from "./ui/controls-view.js";
import { DieView } from "./ui/die-view.js";
import { restartAnimation } from "./ui/dom.js";
import { HeroView } from "./ui/hero-view.js";
import { LaneInput } from "./ui/lane-input.js";
import { LanesView } from "./ui/lanes-view.js";
import { MidiPanel } from "./ui/midi-panel.js";
import { bindShortcuts } from "./ui/shortcuts.js";
import { Toast } from "./ui/toast.js";

// Mediator / composition root: builds the model, the services and the views, and is the one
// place that knows which of them a user action touches. Nothing else imports across layers.
export class App {
  constructor() {
    this.session = new Session();
    this.audio = new AudioEngine();
    this.midi = new MidiOutput(this.audio);
    this.transport = new Transport({ session: this.session, audio: this.audio, midi: this.midi });

    this.die = new DieView();
    this.hero = new HeroView(this.session);
    this.lanes = new LanesView(this.session);
    this.controls = new ControlsView(this.session);
    this.midiPanel = new MidiPanel(this.midi);
    this.toast = new Toast();
    this.modal = new CodeModal();
  }

  // data: a snapshot to restore, else a fresh roll
  start(data) {
    this.die.setFace(5);
    if (!(canRestore(data) && restore(this.session, data))) this.session.roll();
    this.controls.sync(); this.controls.setPlaying(false); this.renderAll();

    this.die.onClick(this.roll);
    this.controls.bind({
      togglePlay: this.togglePlay,
      regenerate: this.regenerate,
      copyCoypu: this.copyCoypu,
      setMaster: this.setMaster,
      setBpm: bpm => { this.session.bpm = bpm; this.controls.showBpm(); this.audio.setDelayTime(this.session.stepDuration); },
      setRnd: pct => { this.session.rnd = pct; this.controls.sync(); },
      setMicro: on => { this.session.micro = on; this.controls.sync(); },
    });
    new LaneInput({
      session: this.session,
      view: this.lanes,
      actions: {
        toggleMute: this.toggleMute,
        rerollTrack: this.rerollTrack,
        setTrackLen: this.setTrackLen,
        setGate: (k, v) => this.session.setGate(k, v),
      },
    }).bind();
    this.modal.bind();
    bindShortcuts({ togglePlay: this.togglePlay, roll: this.roll, regenerate: this.regenerate, closeModal: () => this.modal.close() });

    this.transport.on("state", playing => this.controls.setPlaying(playing));
    this.transport.on("playhead", g => this.lanes.setPlayhead(g));
    this.transport.on("notice", msg => this.toast.show(msg));
    this.midi.on("notice", msg => this.toast.show(msg));
    this.midiPanel.bind();
    if (this.midi.supported) {
      addEventListener("pagehide", () => this.midi.panic());
      this.midi.autoConnect();
    }
  }

  snapshot() { return snapshot(this.session); }

  renderAll() { this.hero.render(); this.lanes.render(); }

  /* ----------------------------- actions ---------------------------- */
  // arrow properties, so they can be handed out as event handlers
  roll = () => this.die.roll(() => { this.session.roll(); this.renderAll(); });

  regenerate = () => { this.session.regenerate(); this.renderAll(); this.controls.spinRegen(); };

  togglePlay = () => this.transport.toggle();

  setMaster = n => {
    if (!this.session.setMaster(n)) return;
    this.transport.wrap(n);
    this.controls.sync();
    this.renderAll();
  };

  setTrackLen = (k, n) => {
    if (!this.session.setTrackLen(k, n)) return;
    this.lanes.fillGrid(k);
    if (this.transport.playing) this.lanes.setPlayhead(this.lanes.patternStep);
  };

  rerollTrack = (k, button) => {
    this.session.rerollTrack(k);
    this.lanes.fillGrid(k);
    restartAnimation(button, "spin");
  };

  toggleMute = k => {
    const muted = this.session.toggleMute(k);
    if (k >= 0) this.audio.setTrackMuted(k, muted);
    this.lanes.updateLane(k);
  };

  copyCoypu = async () => {
    const txt = coypuCode(this.session);
    try { await navigator.clipboard.writeText(txt); this.toast.show("Coypu code copied"); }
    catch (e) { this.modal.open(txt); }
  };
}

import { App } from "./app.js";

// Entry point. Inside the Claude artifact viewer, the hot-reload hook hands back the last
// snapshot and asks for a new one; on a plain page the app just starts with a fresh roll.
const app = new App();
const hot = window.claude?.hot;

function boot(data) {
  app.start(data);
  try { hot?.snapshot?.(() => app.snapshot()); } catch (e) { /* outside the viewer */ }
}

hot?.ready ? hot.ready(boot) : boot(hot?.data ?? {});

