const snapOrig = st => JSON.stringify({ steps: st.steps, scale: st.ctx.scale.key, root: st.ctx.rootPc, h: st.harmony.map(c => c.j), t: st.tracks.map(t => ({ ...t, notes: t.notes.map(n => n && n.m) })) });
