const root = process.argv[2];
const { Session } = await import(root + "/js/sequencer/session.js");
const { isNote, effDur } = await import(root + "/js/sequencer/timeline.js");
const fails = [];
for (let seed = 0; seed < 200; seed++) {
  const s = new Session(); s.roll(); const k = seed % 4;
  s.setTrackLen(k, 5 + seed % 40);
  const tr = s.tracks[k], L = tr.len, snap = JSON.stringify(tr);
  const on = () => Array.from({ length: L }, (_, i) => isNote(tr, i) ? tr.notes[i].m + "/" + effDur(tr, i) : ".");
  const before = on(), hidden = JSON.stringify(tr.gates.slice(L));
  s.rotateTrack(k, 1);
  const r = on();
  if (r.join() !== before.map((_, i) => before[(i - 1 + L) % L]).join()) fails.push("right " + seed);
  s.rotateTrack(k, -1);
  if (JSON.stringify({ ...tr, edited: false }) !== JSON.stringify({ ...JSON.parse(snap), edited: false })) fails.push("undo " + seed);
  for (let i = 0; i < L; i++) s.rotateTrack(k, -1);
  if (on().join() !== before.join()) fails.push("full cycle " + seed);
  if (JSON.stringify(tr.gates.slice(L)) !== hidden) fails.push("hidden " + seed);
  if (!tr.edited) fails.push("edited " + seed);
}
console.log(fails.length ? fails.slice(0, 5) : "rotate: 200 cases ok (right = move later, left undoes it, L shifts = identity, hidden steps untouched, lengths kept)");
